window.businessForm=async id=>{let r={status:'Active',total_hours_worked:0,purchase_date:today()};if(id){const {data}=await sb.from('businesses').select('*').eq('id',id).single();r=data||r;}openModal(`<h3>${id?'Edit':'Add'} Business</h3><form id="businessForm" class="form-grid">${field('Postal','postal',r.postal)}${field('Business Name','name',r.name,true)}${field('Business Type','type',r.type)}${field('Discord Name','owner_name',r.owner_name)}${field('Discord ID','owner_discord_id',r.owner_discord_id)}${field('Job Code','job_code',r.job_code)}${field('Purchase Date','purchase_date',dateOnly(r.purchase_date)==='—'?today():dateOnly(r.purchase_date),false,'date')}${field('Total Hours Worked','total_hours_worked',r.total_hours_worked,false,'number','0.1')}${field('Date Checked','last_activity_check',dateOnly(r.last_activity_check)==='—'?'':dateOnly(r.last_activity_check),false,'date')}${selectField('Status','status',['Active','Review','Inactive','Closed'],r.status||'Active')}${screenshotDropField('businessScreenshot',r.screenshot_url)}${area('Notes','notes',r.notes)}<div class="full"><button class="btn primary">Save Business</button></div></form>`);initScreenshotDrop('businessScreenshot','businesses');$('#businessForm').onsubmit=async e=>{e.preventDefault();const o=formObj(e.target);o.total_hours_worked=Number(o.total_hours_worked||0);o.server='NHRP';o.next_activity_check=(o.status==='Inactive'||o.status==='Closed'||!o.last_activity_check)?null:addDaysIso(o.last_activity_check,30);const res=id?await sb.from('businesses').update(o).eq('id',id).select().single():await sb.from('businesses').insert(o).select().single();if(res.error)return toast(res.error.message);await audit(id?'update':'create','business',res.data.id,{name:o.name});closeModal();toast('Business saved');renderBusinesses();};};
window.businessDetail=async id=>{const [{data:b},{data:p=[]}]=await Promise.all([sb.from('businesses').select('*').eq('id',id).single(),sb.from('payments').select('*').eq('business_id',id).order('payment_date',{ascending:false}).limit(15)]);if(!b)return;openModal(`<h3>${esc(b.name)}</h3><div class="detail-grid">${[['Postal',b.postal],['Business Type',b.type],['Discord Name',b.owner_name],['Discord ID',b.owner_discord_id],['Job Code',b.job_code],['Purchase Date',dateOnly(b.purchase_date)],['Total Hours Worked',Number(b.total_hours_worked||0).toFixed(1)],['Date Checked',dateOnly(b.last_activity_check)],['Status',b.status]].map(x=>`<div class="detail-box"><span>${esc(x[0])}</span><strong>${esc(x[1]||'—')}</strong></div>`).join('')}</div>${b.screenshot_url?`<div class="detail-screenshot"><img src="${esc(b.screenshot_url)}" alt="Business screenshot"><a class="btn secondary small" href="${esc(b.screenshot_url)}" target="_blank" rel="noopener">Open Screenshot</a></div>`:''}<h3>Recent Payments</h3>${table(['Date','Name','Category','Amount'],p.map(x=>[dateOnly(x.payment_date),esc(x.discord_name||x.payer_name),esc(x.category),`$${money(x.amount)}`]))}`);};
window.exportBusinesses=async()=>{const {data=[]}=await sb.from('businesses').select('*').order('name');downloadCsv('nhrp_businesses.csv',['Postal','Business Name','Business Type','Discord Name','Discord ID','Job Code','Purchase Date','Total Hours Worked','Date Checked','Status','Notes','Screenshot'],data.map(r=>[r.postal,r.name,r.type,r.owner_name,r.owner_discord_id,r.job_code,r.purchase_date,r.total_hours_worked,r.last_activity_check,r.status,r.notes,r.screenshot_url]));};

