async function renderBackup(){
  setHead('Backup / Restore','Export or restore NHRP Command Center records');if(!ownerOnly())return $('#content').innerHTML='<div class="empty">Access denied.</div>';
  $('#content').innerHTML=panel('Backup / Restore','SYSTEM',`<div class="backup-box"><h3>Full Data Backup</h3><p class="muted">Downloads Businesses, Factions, Bans, Spawn Codes, 1 of 1, F9, Staff, Training, Payments, Housing, To-Dos, and activity history as one JSON file.</p><button class="btn primary" onclick="backupAll()">Download Backup</button></div><div class="backup-box"><h3>Restore Backup</h3><p class="muted">Restore a backup created by this Command Center. Existing IDs are updated; new IDs are inserted.</p><button class="btn secondary" onclick="restoreBackupDialog()">Choose Backup File</button></div>`);
}
window.backupAll=async()=>{const data={version:'NHRP-COMBINED-1',created_at:new Date().toISOString(),tables:{}};for(const t of APP_TABLES){const {data:rows=[],error}=await sb.from(t).select('*');if(error)return toast(`Backup failed on ${t}: ${error.message}`);data.tables[t]=rows;}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`nhrp_command_center_backup_${today()}.json`;a.click();URL.revokeObjectURL(a.href);await audit('backup','system',null,{tables:APP_TABLES.length});toast('Backup downloaded');};
window.restoreBackupDialog=()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(!confirm('Restore this backup into the Command Center?'))return;try{const json=JSON.parse(await file.text());for(const t of APP_TABLES){const rows=json?.tables?.[t];if(!Array.isArray(rows)||!rows.length)continue;const {error}=await sb.from(t).upsert(rows,{onConflict:'id'});if(error)throw new Error(`${t}: ${error.message}`);}await audit('restore','system',null,{file:file.name});toast('Backup restored');renderDashboard();}catch(err){toast(err.message||'Restore failed');}};input.click();};

async function renderAudit(){
  setHead('Audit Log','Who changed what and when');if(!ownerOnly())return $('#content').innerHTML='<div class="empty">Access denied.</div>';const [{data:logs=[]},{data:profiles=[]}]=await Promise.all([sb.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(300),sb.from('profiles').select('id,display_name,discord_name')]);const names=Object.fromEntries(profiles.map(p=>[p.id,p.display_name||p.discord_name||p.id]));$('#content').innerHTML=panel('Audit Log','SYSTEM',table(['When','User','Action','Entity','ID','Details'],logs.map(r=>[datefmt(r.created_at),esc(names[r.user_id]||'Unknown'),esc(r.action),esc(r.entity_type),code(r.entity_id),`<span class="code">${esc(JSON.stringify(r.details||{}))}</span>`])));
}

async function renderUsers(){
  setHead('Users','Discord access and Command Center permissions');if(!ownerOnly())return $('#content').innerHTML='<div class="empty">Access denied.</div>';const [{data:reg=[]},{data:profiles=[]}]=await Promise.all([sb.from('access_registry').select('*').order('name'),sb.from('profiles').select('*').order('display_name')]);const linked=new Map(profiles.filter(p=>p.discord_id).map(p=>[p.discord_id,p]));const pending=profiles.filter(p=>!p.active&&!reg.some(r=>r.discord_id===p.discord_id));
  const body=`<div class="toolbar" style="margin-bottom:14px"><button class="btn primary" onclick="registryForm()">+ Add User</button></div>${table(['Name','Discord Name','Discord ID','Role','Movement Date','Access','Signed In','Actions'],reg.map(r=>{const p=linked.get(r.discord_id);return[esc(r.name),esc(r.discord_name||p?.discord_name),code(r.discord_id),badge(roleLabel(r.role)),dateOnly(r.movement_date),badge(r.active?'Approved':'Disabled',r.active?'':'danger'),p?'Yes':'Not Yet',`<div class="actions"><button class="btn secondary small" onclick="registryForm('${r.id}')">Edit</button><button class="btn secondary small" onclick="movementHistory('${r.discord_id}')">History</button><button class="btn danger small" onclick="deleteRow('access_registry','${r.id}')">Delete</button></div>`];}))}${pending.length?`<div class="panel-head" style="margin-top:20px"><div><div class="panel-kicker">PENDING</div><h2>Unapproved Sign-Ins</h2></div></div>${table(['Discord Name','Discord ID','Role','Actions'],pending.map(p=>[esc(p.discord_name||p.display_name),code(p.discord_id),esc(roleLabel(p.role)),`<button class="btn primary small" onclick="approvePending('${p.id}')">Review / Approve</button>`]))}`:''}`;$('#content').innerHTML=panel('Users','SYSTEM',body);
}
const userRoles=['owner','executive','director','admin','business_manager','developer','viewer'];
window.registryForm=async id=>{let r={active:true,role:'viewer',movement_date:today()};if(id){const {data}=await sb.from('access_registry').select('*').eq('id',id).single();r=data||r;}openModal(`<h3>${id?'Edit':'Add'} User</h3><form id="registryForm" class="form-grid">${field('Name','name',r.name,true)}${field('Discord Name','discord_name',r.discord_name)}${field('Discord ID','discord_id',r.discord_id,true)}${selectField('Role','role',userRoles.map(x=>({value:x,label:roleLabel(x)})),r.role)}${field('Movement Date','movement_date',dateOnly(r.movement_date)==='—'?today():dateOnly(r.movement_date),false,'date')}<label>Access<select name="active"><option value="true" ${r.active?'selected':''}>Approved</option><option value="false" ${!r.active?'selected':''}>Disabled</option></select></label>${area('Notes','notes',r.notes)}<div class="full"><button class="btn primary">${id?'Save User':'Add User'}</button></div></form>`);$('#registryForm').onsubmit=async e=>{e.preventDefault();const o=formObj(e.target);o.active=o.active==='true';const oldRole=r.role||null;const res=id?await sb.from('access_registry').update(o).eq('id',id).select().single():await sb.from('access_registry').insert({...o,created_by:state.user.id}).select().single();if(res.error)return toast(res.error.message);await sb.from('profiles').update({display_name:o.name,discord_name:o.discord_name,role:o.role,active:o.active,movement_date:o.movement_date}).eq('discord_id',o.discord_id);if(!id||oldRole!==o.role)await sb.from('user_movement_history').insert({discord_id:o.discord_id,name:o.name,discord_name:o.discord_name,from_role:id?oldRole:null,to_role:o.role,movement_date:o.movement_date||today(),change_type:id?'Role Change':'User Added',notes:o.notes,changed_by:state.user.id});await audit(id?'update':'create','access_registry',res.data.id,{discord_id:o.discord_id,role:o.role,active:o.active});closeModal();toast('User saved');renderUsers();};};
window.approvePending=async profileId=>{const {data:p,error}=await sb.from('profiles').select('*').eq('id',profileId).single();if(error)return toast(error.message);openModal(`<h3>Review / Approve User</h3><form id="approveForm" class="form-grid">${field('Name','name',p.display_name||'',true)}${field('Discord Name','discord_name',p.discord_name||'')}<label>Discord ID<input name="discord_id" value="${esc(p.discord_id||'')}" readonly></label>${selectField('Role','role',userRoles.map(x=>({value:x,label:roleLabel(x)})),p.role||'viewer')}${field('Movement Date','movement_date',today(),false,'date')}<div class="full"><button class="btn primary">Approve User</button></div></form>`);$('#approveForm').onsubmit=async e=>{e.preventDefault();const o=formObj(e.target);const {data:r,error:ie}=await sb.from('access_registry').insert({...o,active:true,created_by:state.user.id}).select().single();if(ie)return toast(ie.message);const {error:ue}=await sb.from('profiles').update({display_name:o.name,discord_name:o.discord_name,role:o.role,active:true,movement_date:o.movement_date}).eq('id',profileId);if(ue)return toast(ue.message);await sb.from('user_movement_history').insert({discord_id:o.discord_id,name:o.name,discord_name:o.discord_name,from_role:p.role,to_role:o.role,movement_date:o.movement_date||today(),change_type:'Approved',changed_by:state.user.id});await audit('approve','profile',profileId,{discord_id:o.discord_id,role:o.role});closeModal();toast('User approved');renderUsers();};};
window.movementHistory=async discordId=>{const {data=[],error}=await sb.from('user_movement_history').select('*').eq('discord_id',discordId).order('movement_date',{ascending:false});if(error)return toast(error.message);openModal(`<h3>Movement History</h3>${table(['Movement Date','Change','From','To','Notes'],data.map(r=>[dateOnly(r.movement_date),esc(r.change_type),esc(roleLabel(r.from_role)||'—'),esc(roleLabel(r.to_role)||'—'),esc(r.notes||'—')]))}`);};

function renderSettings(){setHead('Settings','NHRP Command Center configuration');if(!ownerOnly())return $('#content').innerHTML='<div class="empty">Access denied.</div>';$('#content').innerHTML=panel('Settings','SYSTEM',`<div class="settings-list"><div class="setting-row"><span>Server</span><b>NHRP Only</b></div><div class="setting-row"><span>Authentication</span><b>Discord OAuth</b></div><div class="setting-row"><span>Activity Check Frequency</span><b>Every 30 Days</b></div><div class="setting-row"><span>Tracked Activity Categories</span><b>Business • Faction • Housing • 1 of 1</b></div><div class="setting-row"><span>Business Hours Method</span><b>Total Hours Per Check — No Clock In/Out</b></div><div class="setting-row"><span>Spawn Categories</span><b>${SPAWN_CATEGORIES.join(' • ')}</b></div></div>`);}

// ---------------- CSV helpers ----------------
function slug(v){return String(v||'all').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');}
function csvCell(v){const s=String(v??'');return /[",\n\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function downloadCsv(filename,headers,rows){const text=[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');const blob=new Blob([text],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);}
function parseCsv(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else{if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}else field+=c;}}if(field!==''||row.length){row.push(field.replace(/\r$/,''));rows.push(row);}return rows.filter(r=>r.some(v=>String(v).trim()!==''));}
function normalizeHeader(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'');}
function rowObjects(rows){if(rows.length<2)return[];const h=rows[0].map(normalizeHeader);return rows.slice(1).map(r=>Object.fromEntries(h.map((x,i)=>[x,String(r[i]??'').trim()])));}
function pick(o,...keys){for(const k of keys){const n=normalizeHeader(k);if(o[n]!==undefined&&o[n]!=='')return o[n];}return null;}
window.importCsvDialog=kind=>{const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const rows=rowObjects(parseCsv(await file.text()));if(!rows.length)return toast('CSV has no data rows');await importRows(kind,rows);}catch(err){toast(err.message||'Import failed');}};input.click();};
async function importRows(kind,rows){
  let payload=[],tableName=kind,onConflict='id';
  if(kind==='spawn_codes'){payload=rows.map(o=>({name:pick(o,'Name'),spawn_code:pick(o,'Spawn Code','Spawncode'),category:pick(o,'Category','Type')||'Car / SUV',pack:pick(o,'Pack / Resource','Pack'),owner_name:pick(o,'Owner'),notes:pick(o,'Notes'),server:'NHRP'})).filter(x=>x.name&&x.spawn_code);tableName='spawn_codes';onConflict='server,spawn_code';}
  else if(kind==='one_of_ones'){payload=rows.map(o=>{const raw=String(pick(o,'Type')||'Vehicles').toLowerCase();return{discord_name:pick(o,'Discord Name'),discord_id:pick(o,'Discord ID'),type:(raw.includes('gun')||raw.includes('weapon'))?'Guns':'Vehicles',spawn_code:pick(o,'Spawn Code','Spawncode'),add_date:pick(o,'Date','Add Date')||today(),status:pick(o,'Status')||'Active',last_activity_check:pick(o,'Date Checked','Last Activity Check')||null,next_activity_check:addDaysIso(pick(o,'Date Checked','Last Activity Check')||pick(o,'Date','Add Date')||today(),30),screenshot_url:pick(o,'Screenshot','Screenshot URL')};}).filter(x=>x.discord_name&&x.discord_id&&x.spawn_code);tableName='one_of_ones';onConflict='spawn_code';}
  else if(kind==='f9_items'){payload=rows.map(o=>({spawn_code:pick(o,'Spawn Code','Spawncode'),name:pick(o,'Name'),type:pick(o,'Type'),coin_cost:Number(pick(o,'Coin Cost','Coins')||0),screenshot_url:pick(o,'Screenshot','Screenshot URL')})).filter(x=>x.spawn_code&&x.name&&x.type);tableName='f9_items';onConflict='spawn_code';}
  else if(kind==='housing'){payload=rows.map(o=>{const d=pick(o,'Date Added','Date')||today();return{owner_name:pick(o,'Discord Name','Name'),discord_name:pick(o,'Discord Name','Name'),discord_id:pick(o,'Discord ID'),housing_tier:pick(o,'Housing Tier','Tier')||'Tier 1',postal:pick(o,'Postal'),price:Number(pick(o,'Price')||0),add_date:d,status:pick(o,'Status')||'Active',last_activity_check:pick(o,'Date Checked')||null,next_activity_check:addDaysIso(pick(o,'Date Checked')||d,30),server:'NHRP'};}).filter(x=>x.discord_name&&x.discord_id);tableName='housing';onConflict='id';}
  else if(kind==='businesses'){payload=rows.map(o=>{const p=pick(o,'Purchase Date')||today();return{name:pick(o,'Business Name','Name'),type:pick(o,'Business Type','Type'),owner_name:pick(o,'Discord Name','Owner'),owner_discord_id:pick(o,'Discord ID'),job_code:pick(o,'Job Code'),postal:pick(o,'Postal'),purchase_date:p,total_hours_worked:Number(pick(o,'Total Hours Worked','Total Hours')||0),last_activity_check:pick(o,'Date Checked')||null,next_activity_check:addDaysIso(pick(o,'Date Checked')||p,30),status:pick(o,'Status')||'Active',notes:pick(o,'Notes'),screenshot_url:pick(o,'Screenshot','Screenshot URL'),server:'NHRP'};}).filter(x=>x.name);tableName='businesses';onConflict='id';}
  else if(kind==='factions'){payload=rows.map(o=>({name:pick(o,'Faction Name','Name'),type:pick(o,'Type'),leader_name:pick(o,'Leader Discord Name','Leader','Discord Name'),leader_discord_id:pick(o,'Leader Discord ID','Discord ID'),status:pick(o,'Status')||'Active',last_activity_check:pick(o,'Date Checked')||null,next_activity_check:addDaysIso(pick(o,'Date Checked')||today(),30),notes:pick(o,'Notes'),server:'NHRP'})).filter(x=>x.name);tableName='factions';onConflict='id';}
  else if(kind==='bans'){payload=rows.map(o=>({ban_date:pick(o,'Date of Ban','Ban Date')||today(),player_name:pick(o,'Discord Name / Player','Player','Name'),discord_id:pick(o,'Discord ID'),citizen_id:pick(o,'Citizen ID'),license:pick(o,'License'),reason:pick(o,'Reason')||'Imported Ban',duration_text:pick(o,'Duration')||'Unknown',staff_name:pick(o,'Banned By','Staff')||'Imported',evidence:pick(o,'Evidence'),status:pick(o,'Status')||'Active',server:'NHRP'})).filter(x=>x.player_name);tableName='bans';onConflict='id';}
  else if(kind==='staff'){payload=rows.map(o=>({display_name:pick(o,'Name'),discord_name:pick(o,'Discord Name'),discord_id:pick(o,'Discord ID'),rank:pick(o,'Rank'),status:pick(o,'Status')||'Active',hire_date:pick(o,'Hire Date'),movement_date:pick(o,'Movement Date'),notes:pick(o,'Notes'),server:'NHRP'})).filter(x=>x.display_name);tableName='staff';onConflict='id';}
  else if(kind==='staff_training'){payload=rows.map(o=>({staff_name:pick(o,'Staff Name','Name'),discord_name:pick(o,'Discord Name'),discord_id:pick(o,'Discord ID'),training_name:pick(o,'Training'),trainer_name:pick(o,'Trainer'),training_date:pick(o,'Training Date','Date')||today(),notes:pick(o,'Notes')})).filter(x=>x.staff_name&&x.training_name);tableName='staff_training';onConflict='id';}
  else if(kind==='payments'){payload=rows.map(o=>({payer_name:pick(o,'Discord Name','Name')||'Imported',discord_name:pick(o,'Discord Name','Name'),discord_id:pick(o,'Discord ID'),payment_date:pick(o,'Date')||today(),category:pick(o,'Category'),item_name:pick(o,'Add-In / Item','Item'),payment_method:pick(o,'Payment Method'),amount:Number(pick(o,'Amount')||0),notes:pick(o,'Notes'),screenshot_url:pick(o,'Screenshot','Screenshot URL'),server:'NHRP'})).filter(x=>x.discord_name);tableName='payments';onConflict='id';}
  if(!payload.length)return toast('No valid rows found in the CSV.');
  const {error}=await sb.from(tableName).upsert(payload,{onConflict});if(error)return toast(error.message);await audit('import',tableName,null,{rows:payload.length});toast(`Imported ${payload.length} records`);render();
}
window.downloadTemplate=kind=>{const map={spawn_codes:[['Name','Spawn Code','Category','Pack / Resource','Owner','Notes'],[['Example Vehicle','examplecar','Car / SUV','Pack Name','',''],['Example Item','example_item','Items','Inventory Pack','','']]],one_of_ones:[['Discord Name','Discord ID','Type','Spawn Code','Date','Date Checked','Status','Screenshot URL'],[['falco_79','123456789','Vehicles','examplecar',today(),'','Active','']]],f9_items:[['Spawn Code','Name','Type','Coin Cost','Screenshot URL'],[['examplecar','Example Car','Cars/SUVs','250','']]],housing:[['Discord Name','Discord ID','Housing Tier','Postal','Price','Date Added','Date Checked','Status'],[['falco_79','123456789','Tier 2','123','250000',today(),'','Active']]]};const x=map[kind];if(!x)return;downloadCsv(`${kind}_template.csv`,x[0],x[1]);};

async function globalSearch(q){const like=`%${q}%`,out=[];const defs=[['businesses','name,owner_name,owner_discord_id,job_code','name','Business'],['factions','name,leader_name,leader_discord_id','name','Faction'],['bans','player_name,discord_id,reason','player_name','Ban'],['spawn_codes','name,spawn_code,pack','name','Spawn Code'],['one_of_ones','discord_name,discord_id,spawn_code','discord_name','1 of 1'],['f9_items','name,spawn_code,type','name','F9'],['staff','display_name,discord_name,discord_id,rank','display_name','Staff'],['housing','discord_name,owner_name,discord_id,postal','discord_name','Housing']];for(const [t,cols,title,label] of defs){const {data=[]}=await sb.from(t).select('*').or(cols.split(',').map(c=>`${c}.ilike.${like}`).join(',')).limit(6);data.forEach(r=>out.push({title:r[title]||r.owner_name||'Record',sub:label}));}openModal(`<h3>Search Results</h3><div class="search-results">${out.length?out.map(x=>`<div class="search-result"><strong>${esc(x.title)}</strong><div class="muted">${esc(x.sub)}</div></div>`).join(''):'<div class="empty">No matches.</div>'}</div>`);}

boot();
